import os,json,pathlib,pwd,platform,stat
p=pathlib.Path('/proc/637'); out={'uid':os.getuid(),'user':pwd.getpwuid(os.getuid()).pw_name,'boot_id':pathlib.Path('/proc/sys/kernel/random/boot_id').read_text().strip(),'release':platform.release(),'machine':platform.machine(),'scratch_exists':pathlib.Path('/tmp/remoteocd').exists()}
if p.exists():
 out['pid637']={'comm':(p/'comm').read_text().strip(),'status':(p/'status').read_text(),'stat_uid':p.stat().st_uid}
 for name in ('fd','cwd'):
  try: out['pid637'][name]=[x.name for x in (p/name).iterdir()] if name=='fd' else os.readlink(p/name)
  except OSError as e: out['pid637'][name]={'type':type(e).__name__,'message':str(e)}
out['native_processes']=[{'pid':x.name,'comm':(x/'comm').read_text().strip()} for x in pathlib.Path('/proc').iterdir() if x.name.isdigit() and (x/'comm').exists() and (x/'comm').read_text().strip() in ('arduino-cli','remoteocd','openocd','dfu-util')]
print(json.dumps(out))
